/** one evidence row */
function evidenceRow(claim, before, after, unit) {
  // Write your solution here
  return claim + ': ' + before + ' ' + unit + ' ⇒ ' + after + ' ' + unit + ' (' + (after / before).toFixed(1) + '×)';
}

